package com.vinhho.onthi10ai.data.solver

import com.vinhho.onthi10ai.data.solver.OfflineQuizBank.RawQuestion

internal object OfflineQuizBankBiology {

    fun buildForGrade(grade: Int): List<RawQuestion> = when (grade) {
        in 1..5 -> primaryQuestions(grade)
        in 6..9 -> secondaryQuestions(grade)
        else -> highSchoolQuestions(grade)
    }

    private fun primaryQuestions(g: Int): List<RawQuestion> {
        val tag = "[Khoa học / Sinh học Lớp $g]"
        return listOf(
            RawQuestion("$tag Bộ phận nào của cây xanh thực hiện quang hợp chủ yếu?", listOf("Lá cây", "Rễ cây", "Thân cây", "Quả"), 0, "Lá cây chứa chất diệp lục hấp thụ ánh sáng mặt trời để quang hợp."),
            RawQuestion("$tag Bộ phận nào của cây hút nước và muối khoáng từ đất?", listOf("Rễ cây", "Lá cây", "Hoa", "Hạt"), 0, "Lông hút ở rễ cây hút nước và chất khoáng hòa tan nuôi cây."),
            RawQuestion("$tag Cơ quan nào giúp cơ thể người trao đổi khí oxygen và carbon dioxide?", listOf("Phổi", "Dạ dày", "Thận", "Gan"), 0, "Phổi là cơ quan chính của hệ hô hấp."),
            RawQuestion("$tag Cơ quan nào bơm máu đi nuôi khắp các tế bào trong cơ thể?", listOf("Tim", "Phổi", "Não", "Dạ dày"), 0, "Tim co bóp đều đặn giúp máu tuần hoàn liên tục."),
            RawQuestion("$tag Trong các chất sau, nhóm thức ăn giàu chất đạm (protein) là:", listOf("Thịt, cá, trứng, đậu nành", "Gạo, khoai, ngô", "Dầu ăn, mỡ lợn", "Nước lọc"), 0, "Chất đạm giúp xây dựng và đổi mới tế bào cơ thể."),
            RawQuestion("$tag Vitamin C có nhiều trong loại thực phẩm nào giúp tăng sức đề kháng?", listOf("Cam, chanh, bưởi, ổi", "Muối ăn", "Đường kính", "Dầu hỏa"), 0, "Rau xanh và quả chín tươi chứa nhiều vitamin C."),
            RawQuestion("$tag Động vật nào sau đây đẻ con và nuôi con bằng sữa mẹ?", listOf("Cá voi", "Cá chép", "Chim sẻ", "Ếch đồng"), 0, "Cá voi thuộc lớp Thú (động vật có vú) dù sống dưới nước."),
            RawQuestion("$tag Loài vật nào trải qua giai đoạn biến thái từ nòng nọc thành con trưởng thành?", listOf("Ếch", "Rùa", "Thằn lằn", "Chim bồ câu"), 0, "Ếch thuộc lớp Lưỡng cư, nở ra nòng nọc sống dưới nước trước khi lên cạn."),
            RawQuestion("$tag Cây xanh thải ra khí nào trong quá trình quang hợp ban ngày?", listOf("Khí oxygen (O₂)", "Khí carbon dioxide (CO₂)", "Khí amoniac", "Khí metan"), 0, "Nhờ quang hợp, cây xanh cung cấp khí thở O₂ cho sinh vật."),
            RawQuestion("$tag Hiện tượng hạt phấn rơi vào đầu nhụy của hoa gọi là gì?", listOf("Sự thụ phấn", "Sự nảy mầm", "Sự thoát hơi nước", "Sự quang hợp"), 0, "Sau thụ phấn là quá trình thụ tinh để hình thành hạt và quả."),
            RawQuestion("$tag Để phòng tránh bệnh béo phì ở tuổi học sinh, chúng ta cần làm gì?", listOf("Ăn uống cân đối, hạn chế đồ ngọt béo và tăng vận động thể thao", "Ngủ cả ngày và uống nhiều nước ngọt có ga", "Bỏ bữa sáng hoàn toàn", "Chỉ ăn đồ chiên rán"), 0, "Kết hợp dinh dưỡng hợp lí và rèn luyện thể lực hằng ngày."),
            RawQuestion("$tag Cơ quan nào trong cơ thể người tiêu hóa và hấp thụ phần lớn chất dinh dưỡng?", listOf("Ruột non", "Thực quản", "Phế quản", "Thanh quản"), 0, "Ruột non dài và có nhiều lông ruột giúp hấp thụ triệt để dinh dưỡng."),
            RawQuestion("$tag Bệnh sốt xuất huyết lây truyền qua trung gian nào?", listOf("Muỗi vằn", "Ruồi nhà", "Kiến lửa", "Chuột đồng"), 0, "Diệt lăng quăng/bọ gậy và ngủ màn giúp phòng bệnh sốt xuất huyết."),
            RawQuestion("$tag Loại nấm nào sau đây ăn được và giàu dinh dưỡng?", listOf("Nấm rơm, nấm hương", "Nấm độc tán trắng", "Nấm mốc trên bánh mì ôi", "Nấm mốc xanh"), 0, "Tuyệt đối không ăn nấm lạ mọc hoang dại vì dễ ngộ độc."),
            RawQuestion("$tag Trong chuỗi thức ăn: Cỏ → Thỏ → Cáo, sinh vật nào là sinh vật sản xuất tự tạo chất dinh dưỡng?", listOf("Cỏ", "Thỏ", "Cáo", "Vi khuẩn"), 0, "Thực vật xanh tự tổng hợp chất hữu cơ nhờ ánh sáng mặt trời."),
            RawQuestion("$tag Vật trung gian truyền bệnh sốt rét là loài nào?", listOf("Muỗi A-nô-phen", "Ong mật", "Bướm trắng", "Chuồn chuồn"), 0, "Ký sinh trùng sốt rét truyền qua vết đốt của muỗi A-nô-phen cái."),
            RawQuestion("$tag Nên uống đủ khoảng bao nhiêu nước mỗi ngày để cơ thể khỏe mạnh?", listOf("Khoảng 1,5 đến 2 lít nước sạch", "Chỉ uống khi quá khát một cốc nhỏ", "Chỉ uống nước ngọt có ga", "Không cần uống nước"), 0, "Nước chiếm khoảng 70% khối lượng cơ thể và giúp trao đổi chất."),
            RawQuestion("$tag Cơ quan nào điều khiển mọi suy nghĩ và hoạt động của cơ thể?", listOf("Bộ não (hệ thần kinh)", "Lá gan", "Lá lách", "Bàn chân"), 0, "Não bộ là trung tâm điều khiển toàn bộ hệ thần kinh."),
            RawQuestion("$tag Con tằm trải qua mấy giai đoạn trong vòng đời phát triển?", listOf("4 giai đoạn: Trứng → Sâu (tằm) → Nhộng → Ngài (bướm)", "2 giai đoạn", "3 giai đoạn", "5 giai đoạn"), 0, "Tằm nhả tơ kết kén để hóa nhộng trước khi vũ hóa thành ngài."),
            RawQuestion("$tag Để bảo vệ mắt và phòng cận thị học đường, khi đọc sách cần:", listOf("Ngồi đúng tư thế, đủ ánh sáng và giữ khoảng cách khoảng 30–35 cm", "Đọc sách trong bóng tối", "Nằm sấp dí sát mắt vào màn hình", "Đọc liên tục 5 giờ không nghỉ"), 0, "Cho mắt nghỉ ngơi sau mỗi 30–45 phút học tập."),
            RawQuestion("$tag Yếu tố nào KHÔNG phải là điều kiện cần để hạt nảy mầm?", listOf("Đất mặn ngập úng hoàn toàn", "Độ ẩm thích hợp", "Nhiệt độ ấm áp phù hợp", "Không khí (oxygen)"), 0, "Hạt ngâm ngập úng thiếu oxy sẽ bị thối, không nảy mầm được."),
            RawQuestion("$tag Hoa có cả nhị và nhụy trên cùng một bông hoa gọi là:", listOf("Hoa lưỡng tính", "Hoa đơn tính", "Hoa vô tính", "Hoa giả"), 0, "Ví dụ như hoa râm bụt, hoa bưởi, hoa cam là hoa lưỡng tính."),
            RawQuestion("$tag Nhóm thực vật nào sinh sản bằng bào tử thay vì hạt?", listOf("Dương xỉ, rêu", "Cây xoài, cây cam", "Cây ngô, cây lúa", "Cây phượng vĩ"), 0, "Rêu và dương xỉ chưa có hoa và hạt, sinh sản nhờ bào tử."),
            RawQuestion("$tag Chất nào trong khói thuốc lá gây nghiện và có hại nghiêm trọng cho phổi, tim mạch?", listOf("Nicôtin và hắc ín", "Canxi", "Vitamin D", "Sắt"), 0, "Cần nói không với thuốc lá và tránh hít phải khói thuốc thụ động."),
            RawQuestion("$tag Bộ xương người có chức năng chính nào?", listOf("Nâng đỡ cơ thể, bảo vệ nội quan và giúp vận động", "Chỉ để dự trữ nước", "Thực hiện quang hợp", "Tiêu hóa thức ăn"), 0, "Xương sọ bảo vệ não; lồng ngực bảo vệ tim và phổi."),
            RawQuestion("$tag Ở tuổi dậy thì, cơ thể có những biến đổi nhanh chóng về mặt nào?", listOf("Chiều cao, cân nặng, cơ quan sinh dục và tâm sinh lí", "Không có bất kì thay đổi nào", "Ngừng trao đổi chất", "Răng sữa mọc thêm"), 0, "Cần vệ sinh thân thể sạch sẽ và rèn luyện thể thao lành mạnh."),
            RawQuestion("$tag Để phòng bệnh bướu cổ do thiếu khoáng chất vi lượng, ta nên dùng muối có bổ sung chất nào?", listOf("I-ốt (Iodine)", "Chì", "Thủy ngân", "Nhôm"), 0, "Thiếu i-ốt gây phì đại tuyến giáp (bướu cổ) và giảm trí nhớ."),
            RawQuestion("$tag Loại đất nào giữ nước tốt nhất và thường dùng trồng lúa nước ở đồng bằng?", listOf("Đất thịt và đất sét phù sa", "Đất cát khô ven biển", "Đá sỏi trơ trụi", "Bê tông"), 0, "Đất thịt pha sét giữ nước và chất dinh dưỡng tốt cho cây lúa."),
            RawQuestion("$tag Động vật nào thở bằng mang dưới nước?", listOf("Cá chép", "Cá heo", "Chim cánh cụt", "Chó sói"), 0, "Cá chép lấy oxygen hòa tan trong nước qua mang."),
            RawQuestion("$tag Cây xương rồng có lá biến thành gai để thích nghi với môi trường nào?", listOf("Sa mạc khô hạn (giảm thoát hơi nước)", "Đầm lầy ngập mặn", "Đáy đại dương", "Rừng mưa nhiệt đới ẩm"), 0, "Thân xương rồng mọng nước và có màu xanh thực hiện quang hợp."),
            RawQuestion("$tag Hành động nào giúp bảo vệ đa dạng sinh học?", listOf("Bảo tồn rừng tự nhiên, không săn bắt động vật hoang dã", "Đốt rừng làm rẫy", "Đổ hóa chất xuống sông", "Bắt cá bằng thuốc nổ"), 0, "Mỗi loài sinh vật đều giữ vai trò cân bằng trong hệ sinh thái."),
            RawQuestion("$tag Loài côn trùng nào giúp ích rất lớn cho việc thụ phấn của cây ăn quả?", listOf("Ong mật và bướm", "Muỗi vằn", "Châu chấu phá mùa", "Mối gỗ"), 0, "Ong đi hút mật đồng thời mang hạt phấn từ hoa này sang hoa khác."),
            RawQuestion("$tag Cây lúa nước là cây trồng ưa điều kiện nào?", listOf("Ánh sáng dồi dào, khí hậu ấm áp và đủ nước", "Băng tuyết lạnh giá", "Bóng tối hoàn toàn", "Không cần nước"), 0, "Phù hợp với khí hậu nhiệt đới ẩm gió mùa của Việt Nam."),
            RawQuestion("$tag Quá trình cây xanh lấy khí oxygen và thải khí carbon dioxide diễn ra vào thời điểm nào?", listOf("Cả ngày lẫn đêm (quá trình hô hấp của cây)", "Chỉ vào buổi trưa", "Chỉ khi trời mưa", "Cây không bao giờ hô hấp"), 0, "Không nên đặt quá nhiều chậu cây xanh trong phòng ngủ kín ban đêm."),
            RawQuestion("$tag Khi bị đứt tay nhẹ chảy máu, tế bào nào trong máu giúp đông máu cầm máu?", listOf("Tiểu cầu", "Hồng cầu", "Tế bào thần kinh", "Tế bào cơ"), 0, "Tiểu cầu tham gia hình thành cục máu đông bịt kín vết thương."),
            RawQuestion("$tag Chất xơ trong rau xanh và trái cây giúp ích gì cho cơ thể?", listOf("Hỗ trợ tiêu hóa tốt và phòng chống táo bón", "Cung cấp toàn bộ năng lượng thay tinh bột", "Làm xương cứng như sắt", "Thay thế hoàn toàn nước uống"), 0, "Bữa ăn hằng ngày nên có nhiều rau xanh và hoa quả tươi."),
            RawQuestion("$tag Con người thuộc lớp động vật nào trong tự nhiên?", listOf("Lớp Thú (Động vật có vú)", "Lớp Bò sát", "Lớp Chim", "Lớp Lưỡng cư"), 0, "Là loài tiến hóa cao nhất có bộ não và tư duy phát triển vượt bậc."),
            RawQuestion("$tag Cây sống ở vùng đầm lầy ven biển như cây đước thường có loại rễ gì để đứng vững?", listOf("Rễ chống và rễ thở nhô lên khỏi bùn", "Rễ củ tròn lớn", "Không có rễ", "Rễ bám trên đá khô"), 0, "Thích nghi với nền đất bùn lầy ngập thủy triều thiếu khí."),
            RawQuestion("$tag Năng lượng chính giúp hầu hết thực vật trên Trái Đất sinh trưởng đến từ đâu?", listOf("Ánh sáng Mặt Trời", "Ánh sáng đèn pin", "Gió bão", "Tiếng sấm"), 0, "Ánh sáng Mặt Trời khởi đầu dòng năng lượng cho mọi hệ sinh thái."),
            RawQuestion("$tag Biện pháp rửa tay bằng xà phòng trước khi ăn giúp phòng ngừa nhóm bệnh nào?", listOf("Bệnh đường tiêu hóa (tiêu chảy, giun sán) và bệnh truyền nhiễm", "Gãy xương chân", "Cận thị bẩm sinh", "Bệnh còi xương"), 0, "Loại bỏ vi khuẩn, virus bám trên bàn tay.")
        )
    }

    private fun secondaryQuestions(g: Int): List<RawQuestion> {
        val tag = "[KHTN / Sinh học Lớp $g]"
        return listOf(
            RawQuestion("$tag Đơn vị cấu trúc và chức năng cơ bản của mọi cơ thể sống là:", listOf("Tế bào", "Mô", "Cơ quan", "Hệ cơ quan"), 0, "Mọi sinh vật từ đơn bào đến đa bào đều cấu tạo từ tế bào."),
            RawQuestion("$tag Bào quan chỉ có ở tế bào thực vật giúp thực hiện quang hợp là:", listOf("Lục lạp", "Ti thể", "Nhân tế bào", "Ribôxôm"), 0, "Lục lạp chứa sắc tố diệp lục hấp thụ quang năng."),
            RawQuestion("$tag Bào quan thực hiện hô hấp tế bào giải phóng năng lượng ATP là:", listOf("Ti thể", "Lục lạp", "Không bào", "Thành xenlulôzơ"), 0, "Ti thể được ví như nhà máy năng lượng của tế bào."),
            RawQuestion("$tag Vi khuẩn thuộc giới sinh vật nào theo phân loại 5 giới?", listOf("Giới Khởi sinh", "Giới Nguyên sinh", "Giới Nấm", "Giới Thực vật"), 0, "Vi khuẩn là sinh vật đơn bào nhân sơ thuộc Giới Khởi sinh."),
            RawQuestion("$tag Khí nào là nguyên liệu lấy từ không khí cho quá trình quang hợp?", listOf("Carbon dioxide (CO₂)", "Oxygen (O₂)", "Nitrogen (N₂)", "Hydrogen (H₂)"), 0, "6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂ nhờ ánh sáng và diệp lục."),
            RawQuestion("$tag Nước và muối khoáng được vận chuyển từ rễ lên lá qua mạch nào?", listOf("Mạch gỗ", "Mạch rây", "Biểu bì", "Khí khổng"), 0, "Mạch gỗ vận chuyển dòng đi lên; mạch rây vận chuyển chất hữu cơ từ lá đi xuống."),
            RawQuestion("$tag Tế bào máu ở người có chức năng vận chuyển oxygen là:", listOf("Hồng cầu", "Bạch cầu", "Tiểu cầu", "Huyết tương"), 0, "Hồng cầu chứa Hemoglobin (Hb) gắn kết O₂."),
            RawQuestion("$tag Cơ quan lọc máu và tạo nước tiểu ở người là:", listOf("Thận", "Gan", "Dạ dày", "Tụy"), 0, "Mỗi quả thận chứa khoảng một triệu đơn vị chức năng (nephron)."),
            RawQuestion("$tag Bộ nhiễm sắc thể lưỡng bội (2n) ở tế bào sinh dưỡng người bình thường là:", listOf("46 NST (23 cặp)", "23 NST", "44 NST", "48 NST"), 0, "Gồm 22 cặp NST thường và 1 cặp NST giới tính (XX hoặc XY)."),
            RawQuestion("$tag Khi lai hai cơ thể dị hợp Aa × Aa (trội hoàn toàn), tỉ lệ kiểu hình ở F1 là:", listOf("3 trội : 1 lặn", "1 : 1", "100% trội", "1 : 2 : 1"), 0, "Theo quy luật phân li của Menđen: 1 AA : 2 Aa : 1 aa."),
            RawQuestion("$tag Trên hai mạch ADN, các nuclêôtit liên kết theo nguyên tắc bổ sung là:", listOf("A–T và G–X", "A–G và T–X", "A–U và G–X", "A–X và T–G"), 0, "A nối T bằng 2 liên kết hiđrô; G nối X bằng 3 liên kết hiđrô."),
            RawQuestion("$tag Kết thúc giảm phân từ 1 tế bào sinh dục chín (2n) tạo ra:", listOf("4 tế bào con có bộ NST đơn bội (n)", "2 tế bào con có bộ NST 2n", "4 tế bào con có bộ NST 2n", "2 tế bào con có bộ NST n"), 0, "Giảm phân làm giảm số lượng NST đi một nửa để tạo giao tử."),
            RawQuestion("$tag Một đoạn phân tử ADN có A = 300 và G = 600 nuclêôtit. Tổng số nuclêôtit của đoạn ADN này là:", listOf("1.800 nuclêôtit", "900 nuclêôtit", "1.200 nuclêôtit", "3.600 nuclêôtit"), 0, "N = 2A + 2G = 2(300) + 2(600) = 1.800."),
            RawQuestion("$tag Một phân tử ADN có chiều dài 5.100 Å sẽ có tổng số nuclêôtit bằng bao nhiêu?", listOf("3.000 nuclêôtit", "1.500 nuclêôtit", "6.000 nuclêôtit", "2.400 nuclêôtit"), 0, "N = (L × 2) / 3,4 = (5.100 × 2) / 3,4 = 3.000."),
            RawQuestion("$tag Một gen dài 4.080 Å có A = 600 nuclêôtit. Số nuclêôtit loại G của gen đó là:", listOf("600 nuclêôtit", "1.200 nuclêôtit", "300 nuclêôtit", "1.800 nuclêôtit"), 0, "N = 2.400 → A + G = N/2 = 1.200 → G = 1.200 - 600 = 600."),
            RawQuestion("$tag Tổng số liên kết hiđrô của đoạn ADN có A = 400 và G = 500 là:", listOf("2.300 liên kết", "1.800 liên kết", "2.200 liên kết", "900 liên kết"), 0, "H = 2A + 3G = 2(400) + 3(500) = 800 + 1.500 = 2.300."),
